window.UP_CONTENT = window.UP_CONTENT || {};
(window.UP_CONTENT.facts = window.UP_CONTENT.facts || []).push(
  // ---------------- SPACE ----------------
  { id: "sp01", topic: "space", headline: "Jupiter's moon Europa likely hides more water than Earth's oceans", body: "Beneath Europa's icy crust lies a global saltwater ocean, kept liquid by heat from Jupiter's gravity flexing the moon. NASA estimates it holds about twice the water of all Earth's oceans.", q: "What lies beneath the icy surface of Jupiter's moon Europa?", options: ["A global saltwater ocean", "Solid rock all the way down", "Lakes of liquid methane", "A sea of molten lava"], a: 0, explain: "NASA's Europa Clipper, launched in 2024, is headed there to study whether that ocean could support life.", tip: "" },
  { id: "sp02", topic: "space", headline: "Astronaut footprints on the Moon could last for millions of years", body: "The Moon has no wind, no rain and no flowing water to wipe away marks in its dusty soil. Only a slow drizzle of tiny meteorites gradually erodes them.", q: "Why can astronaut footprints on the Moon survive for ages?", options: ["Moon dust is magnetic", "Low gravity glues them in place", "There's no wind or water", "Moonquakes harden them"], a: 2, explain: "Moon dust is jagged and sharp, unlike sand worn smooth by wind and water, so it holds a crisp print.", tip: "" },
  { id: "sp03", topic: "space", legendary: true, headline: "A teaspoon of neutron star would weigh billions of tonnes", body: "A neutron star is the collapsed core of a giant star: more mass than our Sun crushed into a ball about 20 km wide. Its matter is so dense that a teaspoonful would weigh billions of tonnes on Earth.", q: "Roughly what would a teaspoon of neutron star material weigh on Earth?", options: ["About 100 kilograms", "About a tonne", "About a million tonnes", "Billions of tonnes"], a: 3, explain: "Some neutron stars spin hundreds of times per second, sweeping beams of radio waves across space like lighthouses.", tip: "" },
  { id: "sp04", topic: "space", headline: "Venus is the hottest planet, even though Mercury is closer to the Sun", body: "Venus is wrapped in a thick carbon dioxide atmosphere that traps heat in a runaway greenhouse effect. Its surface stays around 465 °C, hot enough to melt lead, day and night.", q: "Which is the hottest planet in our solar system?", options: ["Mercury", "Venus", "Mars", "Jupiter"], a: 1, explain: "Pressure on Venus's surface is about 90 times Earth's, similar to being 900 m deep in the ocean.", tip: "" },
  { id: "sp05", topic: "space", headline: "Saturn's rings are wider than 20 Earths but often just 10 m thick", body: "Saturn's main rings span roughly 270,000 km, yet in most places they are only about 10 metres thick. They are made of countless chunks of water ice, from dust grains to house-sized boulders.", q: "How thick are Saturn's main rings in most places?", options: ["About 10,000 km", "About 500 km", "About 50 km", "About 10 metres"], a: 3, explain: "Scaled to the thickness of a sheet of paper, the rings would be several kilometres wide.", tip: "" },
  { id: "sp06", topic: "space", headline: "Astronauts say space leaves a smell like seared steak and hot metal", body: "After spacewalks, astronauts notice a distinct odour on suits and tools as they come back inside, often described as seared steak, hot metal or welding fumes. One idea is that reactive oxygen atoms clinging to surfaces cause it.", q: "What do astronauts often say spacesuits smell like right after a spacewalk?", options: ["Fresh rain on dry pavement", "Seared steak or hot metal", "Rotten eggs from rocket fuel", "Nothing, as space is odourless"], a: 1, explain: "You can't smell space directly, since a vacuum carries no odour molecules; it's what clings to the suits.", tip: "" },
  { id: "sp07", topic: "space", headline: "Mars has a volcano about two and a half times as tall as Everest", body: "Olympus Mons rises about 22 km, roughly 2.5 times Everest's height above sea level. Mars has weaker gravity and no shifting plates, so lava kept piling up in the same spot for ages.", q: "About how tall is Olympus Mons on Mars compared with Mount Everest?", options: ["About half as tall", "About the same as Everest", "About 2.5 times taller", "About 10 times taller"], a: 2, explain: "Its base is about 600 km across, comparable in area to the US state of Arizona.", tip: "" },
  { id: "sp08", topic: "space", headline: "Astronauts grow a few centimetres taller while living in space", body: "Without gravity pressing down, the discs between the vertebrae relax and expand. Astronauts on long missions can gain up to about 3% of their height, then shrink back after returning to Earth.", q: "What happens to astronauts' height during long stays in space?", options: ["They grow a few cm", "They shrink a little", "No change at all"], a: 0, explain: "The stretch can cause back pain, and the extra height can make spacesuits fit more tightly.", tip: "" },
  { id: "sp09", topic: "space", headline: "The Moon drifts about 3.8 cm farther from Earth every year", body: "We know the Moon is slowly backing away because lasers fired from Earth bounce off mirrors left by Apollo astronauts. Timing the round trip pins down the distance to within millimetres.", q: "How do scientists precisely measure the Moon's slow drift away from Earth?", options: ["Timing changes in ocean tides", "Timing total solar eclipses", "Radar from GPS satellites", "Lasers bounced off mirrors"], a: 3, explain: "Tides cause it: Earth's spin slowly hands energy to the Moon, which also makes our days lengthen very slightly.", tip: "" },
  { id: "sp10", topic: "space", headline: "On Mercury, one sunrise to the next takes two of its years", body: "Mercury spins slowly but orbits fast: it rotates once every 59 Earth days and circles the Sun every 88. Combined, the time from one sunrise to the next is about 176 Earth days.", q: "On Mercury, how does a solar day (sunrise to sunrise) compare to its year?", options: ["About a tenth of a year", "About half a year", "Exactly one year", "About two years"], a: 3, explain: "From some spots on Mercury, the Sun appears to stop and briefly move backwards across the sky.", tip: "" },
  { id: "sp11", topic: "space", headline: "Pluto hasn't finished one orbit since it was discovered in 1930", body: "Pluto takes about 248 Earth years to circle the Sun. Spotted in 1930, it won't complete its first full orbit since discovery until the 2170s.", q: "About how long does Pluto take to orbit the Sun once?", options: ["About 12 years", "About 84 years", "About 248 years", "About 1,000 years"], a: 2, explain: "Its oval orbit sometimes brings it closer to the Sun than Neptune, as happened from 1979 to 1999.", tip: "" },
  { id: "sp12", topic: "space", headline: "Uranus spins on its side, giving each pole 42 years of darkness", body: "Uranus is tilted about 98 degrees, so it rolls around the Sun on its side. Over its 84-year orbit, each pole gets roughly 42 years of sunlight followed by 42 years of night.", q: "Why does each pole of Uranus get about 42 years of darkness at a time?", options: ["It spins tipped on its side", "It's too far to get sunlight", "Its rings block the Sun", "It doesn't rotate"], a: 0, explain: "A giant collision long ago is the leading explanation for the extreme tilt, though it hasn't been proven.", tip: "" },
  { id: "sp13", topic: "space", headline: "The Sun holds about 99.8% of all the mass in our solar system", body: "All the planets, moons, asteroids and comets together add up to only about 0.2% of the solar system's mass. Most of that small remainder belongs to Jupiter.", q: "About what share of the solar system's mass is in the Sun?", options: ["About half", "About 99.8%", "About two-thirds", "About 90%"], a: 1, explain: "Jupiter is so massive that it and the Sun orbit a shared point just outside the Sun's surface.", tip: "" },
  { id: "sp14", topic: "space", legendary: true, headline: "Andromeda's light left it before our species even existed", body: "The Andromeda Galaxy is about 2.5 million light-years away, yet you can see it with the naked eye from a dark site. The light reaching you set off before Homo sapiens appeared, about 300,000 years ago.", q: "When you see the Andromeda Galaxy, roughly how old is the light reaching your eyes?", options: ["About 25,000 years", "About 2,500 years", "About 2.5 million years", "About 250 million years"], a: 2, explain: "It's the most distant object most people can see without a telescope, and holds roughly a trillion stars.", tip: "Try this: On a dark autumn night in the Northern Hemisphere, look near Cassiopeia for Andromeda's faint smudge." },
  { id: "sp15", topic: "space", headline: "Space begins only about 100 km up, an hour's drive straight up", body: "The Karman line, about 100 km above sea level, is the most widely used boundary of space. If you could drive straight up at highway speed, you'd reach it in about an hour.", q: "At roughly what altitude is the most widely used boundary of space?", options: ["About 10 km", "About 100 km", "About 1,000 km", "About 36,000 km"], a: 1, explain: "There's no sharp edge: the US military and NASA award astronaut wings above about 80 km (50 miles).", tip: "" },
  { id: "sp16", topic: "space", headline: "A comet's tail always points away from the Sun, not behind it", body: "A comet's tails are pushed by sunlight and the solar wind, a stream of charged particles from the Sun. So as a comet heads back out of the inner solar system, it travels tail-first.", q: "Which way does a comet's tail point?", options: ["Behind it, along its path", "Away from the Sun", "Toward the Sun", "Toward Earth"], a: 1, explain: "Many comets have two tails: a curved one of dust and a straight, bluish one of electrically charged gas.", tip: "" },
  { id: "sp17", topic: "space", headline: "The Moon's 'dark side' gets just as much sunlight as the near side", body: "The Moon spins exactly once for each trip around Earth, so the same face always points at us. The far side isn't dark; it's just hidden from view, and it gets full sunlight during our new Moon.", q: "Why do we always see the same side of the Moon?", options: ["It spins once per orbit", "It doesn't rotate at all", "Earth's shadow hides the rest", "The far side doesn't reflect light"], a: 0, explain: "This tidal locking is common: many moons in the solar system always show the same face to their planet.", tip: "Try this: Sketch the Moon's craters over a month; you'll see the same features facing you every night." },
  { id: "sp18", topic: "space", headline: "Sunsets on Mars glow blue", body: "On Mars, the sky near the setting Sun turns blue. Fine Martian dust scatters blue light forward, close to the Sun's direction, while the rest of the daytime sky looks butterscotch.", q: "What colour does the sky around the setting Sun look on Mars?", options: ["Red", "Green", "Purple", "Blue"], a: 3, explain: "NASA rovers such as Curiosity have photographed these blue sunsets from the Martian surface.", tip: "" },

  // ---------------- SCIENCE ----------------
  { id: "sc01", topic: "science", headline: "Old windows aren't thicker at the bottom because glass flows", body: "Older glassmaking methods produced panes of uneven thickness, and glaziers often set the thick edge at the bottom. At room temperature, glass would take far longer than the age of the universe to sag noticeably.", q: "Why are some very old window panes thicker at the bottom?", options: ["Uneven panes, set thick end down", "Glass slowly flows down over time", "Rain wore the upper edges thinner"], a: 0, explain: "Some old panes are found thicker at the top or sides too, which a flowing-glass explanation can't account for.", tip: "" },
  { id: "sc02", topic: "science", headline: "Water expands by about 9% when it freezes, enough to burst pipes", body: "Most liquids shrink as they solidify, but water molecules lock into an open, hexagonal crystal when they freeze. That takes up about 9% more space, which is why ice floats and frozen pipes can split.", q: "By roughly how much does water's volume grow when it freezes?", options: ["It shrinks 10%", "About 1%", "About 25%", "About 9%"], a: 3, explain: "Because ice floats, lakes freeze from the top down, and the ice layer insulates the water and life beneath it.", tip: "Try this: Leave a few centimetres of headroom when freezing soups or drinks so containers don't crack." },
  { id: "sc03", topic: "science", headline: "Cornstarch and water turns solid when you punch it", body: "Mix cornstarch with water and you get oobleck, a non-Newtonian fluid. Under sudden force the starch grains jam together and it acts like a solid; press gently and it flows like a liquid.", q: "What happens when you strike a cornstarch-and-water mix (oobleck) hard?", options: ["It splatters everywhere like water", "It foams up and goes runny", "It briefly turns solid-like", "It shatters into dry powder"], a: 2, explain: "With a big enough pool of it, people can run across the surface, but they sink if they stand still.", tip: "Try this: Mix about 2 parts cornstarch to 1 part water in a bowl, then poke it fast and then slowly." },
  { id: "sc04", topic: "science", headline: "Microwave ovens don't cook food from the inside out", body: "Microwaves penetrate only about 1-2 cm into food, making water molecules jiggle and heat up. Deeper parts warm only as that heat slowly conducts inward, which is why thick foods can stay cold in the middle.", q: "How deep do a microwave oven's waves typically reach into food?", options: ["Right to the centre", "Only the outer 1-2 cm", "Only the outer millimetre", "They don't enter food"], a: 1, explain: "Ice absorbs microwaves far less than liquid water, so frozen food tends to thaw unevenly, in patches.", tip: "Try this: Stir microwaved food halfway and let it stand a minute so heat can spread to cold spots." },
  { id: "sc05", topic: "science", headline: "Supercold helium can climb up the walls of its container", body: "Cooled below about -271 °C, helium-4 becomes a superfluid with zero viscosity. It can creep up the walls of its container as a thin film and drip off the bottom.", q: "What strange thing can superfluid helium do?", options: ["Glow blue in the dark when stirred", "Become strongly magnetic when cold", "Creep up and over container walls", "Stay frozen at room temperature"], a: 2, explain: "It can also leak through pores so tiny that they hold ordinary liquids perfectly.", tip: "" },
  { id: "sc06", topic: "science", headline: "Sound travels about four times faster in water than in air", body: "Sound moves at about 1,500 m/s in water versus roughly 340 m/s in air, because water is much harder to compress and passes vibrations along quickly. Whales use this to call across vast distances.", q: "How does the speed of sound in water compare to its speed in air?", options: ["About 4 times faster", "About 4 times slower", "About the same", "About 40 times faster"], a: 0, explain: "In steel, sound moves faster still, at roughly 5,900 m/s.", tip: "Try this: Underwater in a pool, tap two stones together; the click sounds surprisingly sharp and loud." },
  { id: "sc07", topic: "science", headline: "At everyday conditions, graphite is more stable than diamond", body: "Diamond and pencil graphite are both pure carbon; only the arrangement of atoms differs. At surface pressure, graphite is the more stable form, but the change is so slow that diamonds last for billions of years.", q: "What is the key difference between diamond and graphite?", options: ["Diamond also contains silicon", "Graphite contains some lead", "The arrangement of carbon atoms", "Diamond has heavier carbon atoms"], a: 2, explain: "Pencil 'lead' never contained lead: it's graphite mixed with clay.", tip: "" },
  { id: "sc08", topic: "science", legendary: true, headline: "If an atom were a stadium, its nucleus would be a tiny bead", body: "An atom's nucleus is roughly 100,000 times narrower than the atom itself, yet holds over 99.9% of its mass. Scale an atom up to 200 m across and the nucleus would be a 2 mm bead in the middle.", q: "Roughly how much narrower is an atom's nucleus than the whole atom?", options: ["About 10 times", "About 100,000 times", "About 1,000 times", "They're the same width"], a: 1, explain: "The rest is mostly empty space where electrons roam; what feels like solid touch is electrons repelling each other.", tip: "" },
  { id: "sc09", topic: "science", headline: "Salting pasta water doesn't make it boil noticeably faster", body: "Salt actually raises water's boiling point, but a typical spoonful changes it by only a fraction of a degree. The burst of fizzing when you add salt is just crystals giving dissolved gas a place to form bubbles.", q: "What does adding a spoonful of salt to a pot of water do to its boiling?", options: ["Makes it come to a boil much sooner", "Lowers the boiling point by a lot", "Stops the pot from boiling over", "Raises the boiling point slightly"], a: 3, explain: "You'd need about 57 grams of salt per litre to raise the boiling point by just 1 °C.", tip: "Try this: Salt pasta water for flavour, not speed." },
  { id: "sc10", topic: "science", headline: "Stainless steel stays shiny thanks to an invisible, self-healing skin", body: "Stainless steel contains at least about 10.5% chromium. The chromium reacts with oxygen to form an oxide layer only a few nanometres thick that blocks rust, and it re-forms if scratched.", q: "What protects stainless steel from rusting?", options: ["A clear protective lacquer coat", "A thin chromium oxide layer", "It has almost no iron in it", "A thin zinc plating layer"], a: 1, explain: "Salt and harsh cleaners like bleach can break down this layer, which is why stainless steel can still pit or stain.", tip: "Try this: Avoid bleach on stainless steel sinks and rinse off salty spills to keep them looking new." },
  { id: "sc11", topic: "science", headline: "Every rainbow is actually a full circle", body: "Rainbows form as a ring of light around the point directly opposite the Sun from you. From the ground, the horizon cuts off the lower part, but from a plane or high cliff you can sometimes see the whole circle.", q: "What shape is a rainbow really?", options: ["A half circle", "A straight band", "A full circle"], a: 2, explain: "Because each rainbow is centred on your own shadow's direction, no two people see exactly the same one.", tip: "Try this: With the Sun low behind you, spray a fine mist from a garden hose to make your own rainbow." },
  { id: "sc12", topic: "science", headline: "Pressure cookers work by letting water get hotter than 100 °C", body: "Sealing the pot traps steam and raises the pressure inside. At that higher pressure, water boils at about 120 °C instead of 100 °C, and the hotter water and steam cook food much faster.", q: "Why does a pressure cooker cook food faster than a normal pot?", options: ["Steam stirs the food constantly", "It uses hidden microwave heating", "Its thick base heats from all sides", "Water can get hotter than 100 °C"], a: 3, explain: "The reverse happens at high altitude: lower air pressure makes water boil below 100 °C, so cooking takes longer.", tip: "Try this: Use a pressure cooker for dried beans or tough cuts of meat to cut cooking time dramatically." },
  { id: "sc13", topic: "science", headline: "Velcro was invented after burrs stuck to a dog on a hike", body: "In the 1940s, Swiss engineer George de Mestral noticed burdock burrs clinging to his dog's fur. Under a microscope he saw tiny hooks catching on loops, and spent years copying the idea in nylon.", q: "What natural object inspired the invention of Velcro?", options: ["Gecko feet gripping walls", "Sticky strands of spider silk", "The suckers on octopus arms", "Burrs caught in a dog's fur"], a: 3, explain: "The name blends the French words velours (velvet) and crochet (hook).", tip: "" },
  { id: "sc14", topic: "science", headline: "One gram of gold can be hammered to cover over half a square metre", body: "Gold is the most malleable metal. A single gram can be beaten into gold leaf hundreds of times thinner than a human hair, covering more than half a square metre.", q: "Roughly how large a sheet can 1 gram of gold be beaten into?", options: ["Over half a square metre", "About a postage stamp's area", "About a playing card's area"], a: 0, explain: "Gold leaf is so thin that light passes through it, glowing greenish-blue when held up to a lamp.", tip: "" },
  { id: "sc15", topic: "science", headline: "Onions only make you cry once cut: it's a chemical defence", body: "Cutting an onion breaks its cells, letting enzymes produce a volatile chemical called syn-propanethial-S-oxide. It drifts up, stimulates nerves in your eyes, and your tear glands flush it away.", q: "Why does chopping onions make your eyes water?", options: ["A released gas irritates the eyes", "Acidic juice sprays into your eyes", "The sharp smell triggers crying"], a: 0, explain: "The irritant forms only when cells are damaged, such as by a hungry animal's bite, so whole onions don't sting.", tip: "Try this: Chill onions first and use a sharp knife; cleaner cuts crush fewer cells and release less gas." },
  { id: "sc16", topic: "science", legendary: true, headline: "A glass of water holds more molecules than the oceans hold glasses", body: "A glass of water contains about 8 trillion trillion molecules. All of Earth's oceans would fill only about 5 thousand billion billion glasses, so one glass has over 1,000 times more molecules.", q: "Which is larger: molecules in one glass of water, or glasses of water in all the oceans?", options: ["Glasses in the oceans", "Molecules in one glass", "They're roughly the same"], a: 1, explain: "A water molecule is only about 0.3 nanometres across, so even a single sip contains an astronomical number.", tip: "" },
  { id: "sc17", topic: "science", headline: "Mirrors don't flip left and right; they flip front and back", body: "In a mirror, your right hand still appears on the right side of the image. What reverses is front to back; we call it a left-right swap because we imagine turning around to stand where the reflection is.", q: "Which direction does a flat mirror actually reverse?", options: ["Left and right", "Up and down", "Front and back"], a: 2, explain: "That's why ambulances print 'AMBULANCE' backwards on the front: it reads correctly in drivers' rear-view mirrors.", tip: "Try this: Point to your right at a mirror; your reflection points toward the same side of the room." },
  { id: "sc18", topic: "science", headline: "Firework colours come from metals burning in the blast", body: "Each colour comes from a different metal compound heated in the explosion. Strontium gives red, barium green, copper blue and sodium yellow-orange, as their excited atoms release light of specific colours.", q: "Which element gives fireworks their red colour?", options: ["Copper", "Potassium", "Magnesium", "Strontium"], a: 3, explain: "Blue is the hardest firework colour to make bright, because copper compounds break down if the flame gets too hot.", tip: "" },

  // ---------------- EARTH ----------------
  { id: "ea01", topic: "earth", legendary: true, headline: "Ecuador's Chimborazo reaches farther from Earth's centre than Everest", body: "Earth bulges at the equator, so Chimborazo, close to the equator, has a summit about 2 km farther from Earth's centre than Everest's, even though Everest is far higher above sea level.", q: "Which mountain's summit is the farthest point from Earth's centre?", options: ["Mount Everest", "K2", "Chimborazo", "Kilimanjaro"], a: 2, explain: "Earth's diameter at the equator is about 43 km greater than its pole-to-pole diameter.", tip: "" },
  { id: "ea02", topic: "earth", headline: "Measured from its base, Mauna Kea is taller than Mount Everest", body: "Mauna Kea in Hawaii rises about 4,200 m above sea level, but its base sits deep on the Pacific floor. From base to summit it stands about 10,000 m tall, over a kilometre more than Everest.", q: "Measured from its base on the sea floor, about how tall is Mauna Kea?", options: ["About 4,200 m", "About 6,000 m", "About 12,000 m", "About 10,000 m"], a: 3, explain: "Its summit hosts major observatories, thanks to dry, steady air high above most clouds.", tip: "" },
  { id: "ea03", topic: "earth", headline: "The largest desert on Earth is Antarctica, not the Sahara", body: "Deserts are defined by low precipitation, not heat or sand. Antarctica's interior gets only a few centimetres of water-equivalent snow a year, making it the largest desert, ahead of the Arctic and the Sahara.", q: "What makes a place a desert?", options: ["Very high daytime temperatures", "Very little precipitation", "Large areas of sand dunes", "Hot sun and almost no plants"], a: 1, explain: "Its ice is still kilometres thick because, with so little melting, snowfall piled up over hundreds of thousands of years.", tip: "" },
  { id: "ea04", topic: "earth", headline: "The Pacific Ocean is bigger than all of Earth's land put together", body: "The Pacific covers about 165 million square km, more than all of Earth's land combined, which totals about 150 million. It's also the deepest ocean, home to the Mariana Trench.", q: "How does the Pacific Ocean's area compare to all the land on Earth?", options: ["Larger than all land combined", "About half of all land combined", "About a tenth of all land area"], a: 0, explain: "It is slowly shrinking by a few centimetres a year as plates around its rim dive beneath neighbouring ones.", tip: "" },
  { id: "ea05", topic: "earth", headline: "Continents drift about as fast as your fingernails grow", body: "Tectonic plates move a few centimetres a year, roughly fingernail speed. GPS stations now measure it directly: North America and Europe are moving apart by about 2.5 cm each year.", q: "About how fast do Earth's tectonic plates move?", options: ["A few metres per year", "A few centimetres per year", "A few millimetres per century", "They don't move"], a: 1, explain: "Over about 200 million years, that slow creep opened up the entire Atlantic Ocean.", tip: "" },
  { id: "ea06", topic: "earth", headline: "In Iceland you can dive in a crack between two tectonic plates", body: "Iceland sits on the Mid-Atlantic Ridge, where the North American and Eurasian plates pull apart. At the Silfra fissure, divers float in glacier-fed water so clear they can often see over 100 m.", q: "In Iceland's Silfra fissure, divers swim in a rift between which two plates?", options: ["Pacific and North American", "South American and African", "North American and Caribbean", "North American and Eurasian"], a: 3, explain: "Iceland widens by about 2 cm a year as the plates separate, and the gap fills with new volcanic rock.", tip: "" },
  { id: "ea07", topic: "earth", headline: "Lake Baikal holds about 20% of Earth's unfrozen surface fresh water", body: "Lake Baikal is the deepest lake on Earth at about 1,640 m, and one of the oldest, at roughly 25 million years. It holds more water than all five North American Great Lakes combined.", q: "About what share of Earth's unfrozen fresh surface water is in Lake Baikal?", options: ["About 1%", "About 5%", "About 20%", "About 60%"], a: 2, explain: "It's home to the nerpa, one of the only seals that live entirely in fresh water.", tip: "" },
  { id: "ea08", topic: "earth", headline: "Earth's longest mountain range is almost entirely underwater", body: "The mid-ocean ridge system winds about 65,000 km around the globe like the seam on a baseball. Hot rock rises along it and forms new sea floor, slowly pushing plates apart.", q: "Where is Earth's longest mountain range?", options: ["The Andes range", "Under the ocean", "The Himalayas", "The Rocky Mountains"], a: 1, explain: "The Andes, the longest range on land, is about 7,000 km long, roughly a tenth as long.", tip: "" },
  { id: "ea09", topic: "earth", headline: "Falling raindrops aren't teardrop-shaped", body: "Small raindrops are nearly perfect spheres, held together by surface tension. Bigger ones get flattened by air resistance into a hamburger-bun shape, and drops wider than about 5 mm usually break apart.", q: "What shape is a typical falling raindrop?", options: ["Round or bun-shaped", "Teardrop-shaped", "Long and needle-like"], a: 0, explain: "The classic teardrop shape comes from drips hanging off taps and leaves, not from drops in free fall.", tip: "" },
  { id: "ea10", topic: "earth", headline: "Snow is made of clear ice, yet it looks white", body: "Each snow crystal is clear ice, but a snowbank holds countless crystal faces. Light bounces off them in every direction, scattering all colours about equally, and our eyes read that mix as white.", q: "Why does snow look white even though ice is clear?", options: ["It contains white mineral dust", "The cold bleaches the colour out", "Its crystals scatter all colours", "It reflects the white cloud cover"], a: 2, explain: "Deep holes in snow and thick glacier ice can look blue, because ice absorbs a little red light over long paths.", tip: "Try this: Next deep snowfall, push a stick far into the snow and peek into the hole for a faint blue glow." },
  { id: "ea11", topic: "earth", headline: "The Dead Sea's shore is the lowest dry land on Earth", body: "The shore of the Dead Sea lies more than 400 m below sea level. Its level keeps dropping by about a metre a year, largely because water from the Jordan River is diverted before it arrives.", q: "Where is the lowest dry land on Earth?", options: ["Death Valley", "The Netherlands", "Caspian Sea shore", "Dead Sea shore"], a: 3, explain: "Its water is roughly ten times saltier than the ocean, so swimmers float with almost no effort.", tip: "" },
  { id: "ea12", topic: "earth", headline: "The Amazon carries about a fifth of all river water reaching the sea", body: "The Amazon discharges more water than the next several largest rivers combined. Its outflow is so strong that fresher water can be detected far out into the Atlantic Ocean.", q: "About what share of all river water flowing into the oceans comes from the Amazon?", options: ["About 2%", "About 20%", "About 50%", "About 80%"], a: 1, explain: "Despite its size, no bridge crosses the main Amazon River, partly because its banks shift and flood.", tip: "" },
  { id: "ea13", topic: "earth", legendary: true, headline: "The Sahara was green, with lakes and hippos, about 8,000 years ago", body: "During the African Humid Period, roughly 11,000 to 5,000 years ago, a wobble in Earth's orbit strengthened monsoon rains. The Sahara held grasslands and lakes, with hippos, crocodiles and herds of grazers.", q: "What was the Sahara like roughly 8,000 years ago?", options: ["Covered by glaciers and snowfields", "Under a warm, shallow inland sea", "Green with lakes and grassland", "Much the same as today's desert"], a: 2, explain: "Rock art deep in the desert shows cattle herding and what appear to be people swimming from that greener era.", tip: "" },
  { id: "ea14", topic: "earth", headline: "Earth's inner core is roughly as hot as the surface of the Sun", body: "Earth's solid inner core is around 5,000 °C or more, comparable to the Sun's surface at about 5,500 °C. It stays solid because the crushing pressure there keeps the iron from melting.", q: "Roughly how hot is Earth's inner core?", options: ["As hot as the Sun's surface", "About as hot as boiling water", "About as hot as a pizza oven"], a: 0, explain: "Heat from the core stirs the liquid iron outer core, and that churning generates Earth's magnetic field.", tip: "" },
  { id: "ea15", topic: "earth", headline: "Earth's magnetic poles have swapped places hundreds of times", body: "Earth's magnetic field has reversed hundreds of times. The last full flip was about 780,000 years ago, recorded in lava and sea-floor rocks whose magnetic minerals locked in the field's direction as they cooled.", q: "Roughly when did Earth's magnetic field last fully reverse?", options: ["About 2,000 years ago", "About 50 million years ago", "It has never reversed", "About 780,000 years ago"], a: 3, explain: "Reversals are irregular: the gaps between them range from tens of thousands to millions of years.", tip: "" },
  { id: "ea16", topic: "earth", headline: "Melting all of Antarctica's ice would raise seas about 60 metres", body: "Antarctica's ice sheet is up to nearly 5 km thick and holds most of the world's fresh water. If all of it melted, global sea level would rise by roughly 60 metres.", q: "If all of Antarctica's ice melted, roughly how much would sea level rise?", options: ["About 60 cm", "About 6 m", "About 60 m", "About 600 m"], a: 2, explain: "The ice is so heavy that it presses the land beneath it down, in places below sea level.", tip: "" },
  { id: "ea17", topic: "earth", headline: "A fluffy cumulus cloud can hold hundreds of tonnes of water", body: "A typical small cumulus cloud holds roughly 500 tonnes of water as tiny droplets. They stay aloft because each droplet is so small that rising air and air resistance easily keep it floating.", q: "Roughly how much water can a typical small cumulus cloud hold?", options: ["A few kilograms", "Hundreds of tonnes", "About one tonne", "Billions of tonnes"], a: 1, explain: "It takes about a million cloud droplets to make one average raindrop.", tip: "" },
  { id: "ea18", topic: "earth", headline: "Mainland Australia is wider than the Moon", body: "Mainland Australia stretches about 4,000 km from east to west, while the Moon is about 3,500 km across. The Moon is a sphere, though, so its total surface area is far larger.", q: "Which is wider: mainland Australia or the Moon?", options: ["Mainland Australia", "The Moon", "They're about the same"], a: 0, explain: "Australia drifts north by about 7 cm a year, one of the fastest-moving continents.", tip: "" },

  // ---------------- NATURE ----------------
  { id: "na01", topic: "nature", headline: "Wombats produce cube-shaped poop", body: "Wombats are the only animals known to make cubic droppings. Researchers found that the walls of their intestine vary in stiffness, shaping flat sides and corners as the feces slowly dry out.", q: "What shape are wombat droppings?", options: ["Spheres", "Spirals", "Discs", "Cubes"], a: 3, explain: "Wombats leave the cubes on rocks and logs as scent markers, and the flat sides may help keep them from rolling away.", tip: "" },
  { id: "na02", topic: "nature", headline: "Sea otters hold paws or wrap in kelp so they don't drift apart", body: "Sea otters sleep floating on their backs. To avoid drifting away from their group, they may hold paws with each other or wrap themselves in kelp, which anchors them in place.", q: "Why do sea otters hold paws or wrap themselves in kelp while resting?", options: ["To keep each other warm", "To avoid drifting away", "To hide from passing sharks", "To guard their shared food"], a: 1, explain: "With no blubber, they rely on the densest fur of any animal, up to about a million hairs per square inch.", tip: "" },
  { id: "na03", topic: "nature", headline: "Tardigrades have survived exposure to the vacuum of space", body: "Tardigrades, or water bears, are animals under a millimetre long that can dry out into a dormant 'tun'. In 2007, dried tardigrades spent 10 days exposed to space in orbit, and many survived.", q: "What lets tardigrades survive extremes like the vacuum of space?", options: ["A tough, metal-rich outer shell", "Making their own oxygen supply", "Drying into a dormant 'tun'"], a: 2, explain: "In the tun state their metabolism almost stops; add water and many revive within hours.", tip: "" },
  { id: "na04", topic: "nature", headline: "About half the oxygen made on Earth comes from tiny ocean plankton", body: "Microscopic phytoplankton drift in sunlit surface waters and photosynthesize like plants. Together they produce roughly half of Earth's oxygen, rivalling all the forests and grasslands on land.", q: "Roughly how much of Earth's oxygen is produced by ocean phytoplankton?", options: ["About 5%", "About 20%", "About half", "Nearly all"], a: 2, explain: "Phytoplankton also form the base of most ocean food webs, feeding everything from krill to whales.", tip: "" },
  { id: "na05", topic: "nature", headline: "A hummingbird's heart can beat over 1,200 times a minute", body: "Some hummingbirds' hearts beat over 1,200 times a minute while flying. To survive cold nights without food, many drop into torpor, slowing their heart and letting their body cool dramatically.", q: "How fast can a hummingbird's heart beat?", options: ["About 60 bpm", "About 120 bpm", "Roughly 400 bpm", "Over 1,000 bpm"], a: 3, explain: "Hummingbirds are among the few birds that can fly backwards.", tip: "" },
  { id: "na06", topic: "nature", headline: "Crows remember the faces of people who wronged them, for years", body: "In a University of Washington study, researchers trapped crows while wearing a particular mask. For years afterward, crows scolded anyone wearing that mask, including birds that had never been caught.", q: "What can wild crows remember about individual humans?", options: ["Only their clothing colour", "Their faces, for years", "Their voices, for minutes"], a: 1, explain: "Crows that weren't trapped learned to scold the mask too, suggesting they pass on threats socially.", tip: "" },
  { id: "na07", topic: "nature", headline: "Koala fingerprints are almost impossible to tell apart from ours", body: "Koalas have fingerprints with loops and whorls so similar to human ones that they're hard to distinguish even under a microscope. They evolved independently, perhaps to help grip branches and handle leaves.", q: "Which animal has fingerprints remarkably similar to humans'?", options: ["Dogs", "Dolphins", "Parrots", "Koalas"], a: 3, explain: "Our close relatives, chimps and gorillas, have fingerprints too, but koalas evolved theirs separately.", tip: "" },
  { id: "na08", topic: "nature", legendary: true, headline: "A whole aspen forest in Utah is one single living organism", body: "Pando, in Utah, looks like a grove of about 47,000 quaking aspen trunks, but they're genetically identical stems sprouting from one shared root system. It weighs an estimated 6,000 tonnes.", q: "What makes the aspen grove called Pando remarkable?", options: ["It's one clone, ~47,000 stems", "It's the tallest tree alive", "It's a giant underground fungus", "Its trees never lose leaves"], a: 0, explain: "It's among the heaviest known organisms; its exact age is uncertain, with estimates of many thousands of years.", tip: "" },
  { id: "na09", topic: "nature", headline: "Elephants can pick up distant rumbles through their feet", body: "Elephants make deep rumbles that travel through the ground as well as the air. Sensitive receptors in their feet and trunks can detect these vibrations, helping them sense other elephants far away.", q: "How can elephants detect rumbles from distant elephants?", options: ["Watching distant herds' ear flaps", "Sensing vibrations with their feet", "Smelling scent carried on the wind", "Seeing dust kicked up by distant herds"], a: 1, explain: "Elephants have been seen leaning forward or lifting a foot, apparently to sense ground vibrations better.", tip: "" },
  { id: "na10", topic: "nature", headline: "A mantis shrimp's punch is so fast it makes the water collapse", body: "The peacock mantis shrimp strikes with a club-like limb so fast it rips the water into vapour bubbles. When those bubbles collapse, they deliver a second shock, enough to help crack snail shells.", q: "What creates the second shock wave in a mantis shrimp's strike?", options: ["A burst of electric current", "A squirt of stunning venom", "Its shell cracking like a whip", "Collapsing vapour bubbles"], a: 3, explain: "Each strike is over in a few thousandths of a second, one of the fastest movements in the animal world.", tip: "" },
  { id: "na11", topic: "nature", headline: "Some bamboo can grow nearly a metre in a single day", body: "Certain bamboo species are the fastest-growing plants on Earth, adding up to about 90 cm a day. A shoot emerges with its segments already formed, and growth comes mostly from those sections stretching.", q: "How fast can the fastest-growing bamboo species grow?", options: ["Nearly 1 m a day", "About 1 cm per day", "About 10 m a day"], a: 0, explain: "Bamboo is a giant grass, not a tree, related to the grasses in lawns and grain fields.", tip: "" },
  { id: "na12", topic: "nature", headline: "No single monarch butterfly completes the whole migration", body: "Monarch butterflies in eastern North America fly up to about 4,800 km to spend winter in Mexico. No individual makes the round trip; it takes several generations to return north.", q: "How many monarch generations does it take to complete their yearly migration cycle?", options: ["Just one", "Several", "Hundreds", "Thousands"], a: 1, explain: "The generation that flies south can live around eight months, versus just a few weeks for summer monarchs.", tip: "" },
  { id: "na13", topic: "nature", headline: "A Venus flytrap counts touches before it snaps shut", body: "A Venus flytrap's trap closes only when its trigger hairs are touched twice within about 20 seconds. This helps it ignore raindrops, and further touches signal it to start releasing digestive enzymes.", q: "What does a Venus flytrap need before its trap snaps shut?", options: ["One firm touch of a trigger hair", "Direct sunlight falling on the trap", "Two touches within ~20 seconds"], a: 2, explain: "The trap can close in about a tenth of a second, one of the fastest movements in the plant world.", tip: "Try this: If you keep a flytrap, don't trigger it for fun; each closing costs the plant energy." },
  { id: "na14", topic: "nature", headline: "Sloths grow algae in their fur", body: "Sloth hairs have grooves that soak up water, where green algae grow and tint the fur. Moths live in the fur too, and the greenish tinge may help sloths blend into the treetops.", q: "What grows in sloth fur, giving it a green tint?", options: ["Moss", "Algae", "Mushrooms", "Lichen"], a: 1, explain: "Sloths move so slowly that they typically climb down only about once a week to relieve themselves.", tip: "" },
  { id: "na15", topic: "nature", headline: "Axolotls can regrow legs, spinal cord and even heart tissue", body: "Axolotls, salamanders from lakes near Mexico City, can regrow lost limbs, tails, parts of the spinal cord and heart tissue, often without scarring. Scientists study them to learn how healing works.", q: "Which body parts can axolotls regenerate?", options: ["Limbs, spinal cord and more", "Only their tails, like lizards", "Only their skin and gills", "Nothing beyond small wounds"], a: 0, explain: "Though common as pets and in labs, they're critically endangered in the wild, surviving mainly in Xochimilco's canals.", tip: "" },
  { id: "na16", topic: "nature", legendary: true, headline: "Arctic terns chase endless summer, flying about 70,000 km a year", body: "Arctic terns breed in the Arctic summer, then fly to Antarctica for the southern summer. Tracking shows they cover roughly 70,000 km a year, seeing more daylight than any other animal.", q: "Why do Arctic terns see more daylight than any other animal?", options: ["They follow summer pole to pole", "They fly high above the cloud layer", "They stay near the sunny equator", "They rarely sleep, even in flight"], a: 0, explain: "Over a 30-year life, a tern may fly the distance of about three round trips to the Moon.", tip: "" },
  { id: "na17", topic: "nature", headline: "Bottlenose dolphins use signature whistles much like names", body: "Each bottlenose dolphin develops its own signature whistle. Studies show they respond when their whistle is played back, and copy others' whistles, much like calling someone by name.", q: "What do bottlenose dolphins use in a way similar to names?", options: ["Rhythmic fin slaps", "Shaped bubble rings", "Signature whistles", "Unique tail patterns"], a: 2, explain: "Calves develop their signature whistle in their first months of life, and many keep it for decades.", tip: "" },
  { id: "na18", topic: "nature", headline: "Mature sunflowers stop following the Sun and face east", body: "Young sunflowers track the Sun from east to west by day and swing back overnight, guided by an internal clock. Once they bloom, most stop moving and face east permanently.", q: "Which way do most mature, blooming sunflower heads face?", options: ["They follow the Sun", "Toward the east", "Toward the west", "Straight up at the sky"], a: 1, explain: "In a 2016 study, east-facing heads warmed faster in the morning and drew about five times more bee visits.", tip: "Try this: Visit a sunflower field in the morning and check: most flower heads will be facing east." },

  // ---------------- BODY ----------------
  { id: "bo01", topic: "body", headline: "Your stomach replaces its inner lining every few days", body: "Stomach acid is strong, with a pH of around 1.5 to 3.5. A thick mucus layer shields the stomach wall, and its surface cells are replaced every few days to repair any damage.", q: "What stops stomach acid from digesting the stomach itself?", options: ["The acid is too weak to harm it", "Its walls are coated in fat", "Mucus and fast cell renewal", "Saliva neutralizes the acid"], a: 2, explain: "Most stomach ulcers are linked to H. pylori bacteria that weaken this barrier, a discovery that won a 2005 Nobel Prize.", tip: "" },
  { id: "bo02", topic: "body", headline: "You're about 1 cm taller when you wake up than at bedtime", body: "During the day, gravity squeezes fluid out of the cushioning discs between your vertebrae, so you shrink slightly. Lying down overnight lets them soak up fluid and expand again.", q: "At what time of day are most people tallest?", options: ["In the morning", "In the afternoon", "In the evening", "It never changes"], a: 0, explain: "It's the same effect that lets astronauts temporarily grow a few centimetres taller in space.", tip: "Try this: Measure your height right after waking and again before bed, and compare." },
  { id: "bo03", topic: "body", headline: "The clear front of your eye gets oxygen straight from the air", body: "The cornea has no blood vessels, which keeps it crystal clear. Instead it absorbs oxygen from the air through the tear film, and gets nutrients from tears and the fluid behind it.", q: "Where does the cornea of your eye get most of its oxygen?", options: ["Blood vessels inside it", "Directly from the air", "The optic nerve"], a: 1, explain: "That's why contact lenses must let oxygen through to the eye.", tip: "Try this: Take contact lenses out before sleeping unless your eye doctor says they're approved for overnight wear." },
  { id: "bo04", topic: "body", headline: "Muscle can't turn into fat; they're completely different tissues", body: "Muscle and fat are made of different cell types, so one can't transform into the other. If you stop training, muscles may shrink while fat grows, which can look like one turned into the other.", q: "Can muscle turn into fat if you stop exercising?", options: ["Yes, gradually, over many months", "Yes, but only after age 40", "No, they're different tissues"], a: 2, explain: "Muscle mass naturally declines with age, but strength training at any age can help slow that loss.", tip: "Try this: Do muscle-strengthening activities on at least two days a week, as WHO recommends for adults." },
  { id: "bo05", topic: "body", headline: "Your brain replays and strengthens new memories while you sleep", body: "During sleep, the brain replays patterns of activity from the day and strengthens many new memories. People who sleep after learning typically remember more than those who stay awake.", q: "When does the brain strengthen many of the day's new memories?", options: ["Only while re-reading", "While you sleep", "During big meals"], a: 1, explain: "Adults generally need 7 or more hours a night; short sleep also makes it harder to learn new things the next day.", tip: "Try this: Review tricky material in the evening, then protect a full night's sleep." },
  { id: "bo06", topic: "body", headline: "Humans have far more than five senses, including a sense of position", body: "Beyond sight, hearing, taste, smell and touch, you sense balance, temperature, pain and your body's position. Proprioception, from sensors in muscles and joints, tells you where your limbs are.", q: "Which sense tells you where your limbs are, even with your eyes closed?", options: ["Vestibular sense", "Thermoception", "Interoception", "Proprioception"], a: 3, explain: "Your inner ear's balance system is another 'hidden' sense, which is why spinning around makes you dizzy.", tip: "Try this: Close your eyes and touch your nose with a fingertip; that's proprioception at work." },
  { id: "bo07", topic: "body", headline: "Newborns have about 300 bones; adults end up with 206", body: "A newborn's skeleton includes many separate bones and pieces of cartilage. As children grow, many of them fuse together, such as in the skull and lower spine, leaving most adults with 206.", q: "Why do adults have fewer bones than newborn babies?", options: ["Bones fuse as we grow", "Bones dissolve with age", "Babies have extra ribs"], a: 0, explain: "A baby's skull bones are separated by soft spots called fontanelles, which let the head flex during birth.", tip: "" },
  { id: "bo08", topic: "body", headline: "About a fifth of the water you take in comes from food", body: "Fruits, vegetables, soups and other foods are often mostly water. For a typical diet, food supplies roughly 20% of daily water intake, and drinks of all kinds supply the rest.", q: "Roughly what share of daily water intake typically comes from food?", options: ["About 20%", "Almost none", "About 80%"], a: 0, explain: "Cucumbers, lettuce and watermelon are over 90% water.", tip: "Try this: Check your urine colour; pale yellow usually means you're well hydrated." },
  { id: "bo09", topic: "body", headline: "Your gut has its own nervous system of about 500 million neurons", body: "The enteric nervous system lines your digestive tract with roughly 500 million neurons. It can run digestion on its own, while staying in contact with the brain through the vagus nerve.", q: "What controls much of digestion, even without input from the brain?", options: ["The spleen, beside the stomach", "The gut's own nervous system", "Hormones from the thyroid gland", "Reflexes in the spinal cord"], a: 1, explain: "It's often nicknamed the 'second brain', though it manages digestion rather than conscious thought.", tip: "" },
  { id: "bo10", topic: "body", legendary: true, headline: "Your body gives off a faint visible glow, too dim for eyes to see", body: "Chemical reactions in your cells release tiny amounts of visible light. A 2009 study in Japan captured this glow with ultra-sensitive cameras: it's about 1,000 times weaker than our eyes can detect.", q: "How bright is the faint visible light the human body gives off?", options: ["Far too dim for our eyes to see", "About as bright as a dim candle", "About as bright as a firefly", "Just visible in a pitch-dark room"], a: 0, explain: "In that study the glow rose and fell over the day, and was brightest on the face, especially the cheeks.", tip: "" },
  { id: "bo11", topic: "body", headline: "Every area of your tongue can taste sweet, salty, sour and bitter", body: "The famous 'tongue map' came from a misread 1901 German study. In fact, taste buds all over the tongue detect all the basic tastes, including umami, the savoury taste of broth and parmesan.", q: "Which part of the tongue can detect sweet tastes?", options: ["Only the very tip", "Only the back edge", "Only the two sides", "The whole tongue"], a: 3, explain: "Sensitivity varies only slightly from region to region, too little for most people to notice.", tip: "Try this: Dab a little sugar water on different parts of your tongue; you'll taste sweet everywhere." },
  { id: "bo12", topic: "body", headline: "There are no muscles inside your fingers", body: "Your fingers contain bones, tendons, nerves and blood vessels, but no muscles. Muscles in your forearm and palm pull on long tendons, like strings on a puppet, to bend and straighten them.", q: "What mainly moves your fingers?", options: ["Small muscles inside each finger", "Muscles in the palm and forearm", "Tendons that contract on their own"], a: 1, explain: "Carpal tunnel syndrome happens where these tendons and a nerve squeeze through a narrow passage in the wrist.", tip: "Try this: Wiggle your fingers while holding your forearm; you'll feel the muscles there doing the work." },
  { id: "bo13", topic: "body", headline: "Goosebumps are a leftover from when our ancestors had thick fur", body: "Tiny muscles at the base of each hair contract when you're cold or emotional, making hairs stand up. In furry animals this traps insulating air or makes them look bigger; in us it mostly just makes bumps.", q: "What did the goosebump reflex do for our furry ancestors?", options: ["Helped them sweat more freely", "Grew new hair to replace lost fur", "Sharpened their sense of touch", "Fluffed fur for warmth or size"], a: 3, explain: "Porcupines raise their quills, which are modified hairs, using the same kind of reflex.", tip: "" },
  { id: "bo14", topic: "body", headline: "Tooth enamel is the hardest substance in your body", body: "Enamel is about 96% mineral, mostly crystals of hydroxyapatite, making it harder than bone. But it contains no living cells, so unlike bone it can't repair itself once it's damaged.", q: "What is the hardest substance in the human body?", options: ["The thigh bone", "Fingernails", "Tooth enamel", "Knee cartilage"], a: 2, explain: "Fluoride helps by making enamel's crystals more resistant to acids from bacteria and food.", tip: "Try this: Brush twice a day with fluoride toothpaste, and spit out the foam rather than rinsing." },
  { id: "bo15", topic: "body", headline: "You're not 90% bacteria: microbes roughly match your own cells", body: "An old estimate claimed bacteria outnumber human cells 10 to 1. A 2016 recount found about 38 trillion bacteria versus about 30 trillion human cells, roughly a 1 to 1 ratio.", q: "How does the number of bacteria in your body compare to your own cells?", options: ["About 10 to 1", "Roughly equal", "About 1 to 100", "About 1,000 to 1"], a: 1, explain: "Most of those microbes live in your large intestine, and together they weigh only about 0.2 kg.", tip: "Try this: Eat a variety of fibre-rich plant foods, which help feed your gut microbes." },
  { id: "bo16", topic: "body", headline: "Morning daylight is the strongest signal for setting your body clock", body: "Light-sensitive cells in your eyes send signals to a master clock in the brain. Bright morning light keeps this daily rhythm in sync, helping you feel alert by day and sleepy at night.", q: "What is the strongest everyday cue for keeping your body clock in sync?", options: ["A big breakfast", "A cold shower", "Bright daylight", "Loud music"], a: 2, explain: "Even on cloudy days, outdoor light is usually many times brighter than typical indoor lighting.", tip: "Try this: Spend some time outdoors in daylight soon after waking, and dim bright screens late at night." },
  { id: "bo17", topic: "body", headline: "Each of your eyes has a blind spot your brain quietly fills in", body: "Where the optic nerve leaves the back of the eye, there are no light-sensing cells, creating a blind spot. You don't notice because your brain fills the gap using the surroundings and the other eye.", q: "Why does each eye have a blind spot?", options: ["Eyelashes block that part of view", "Tears pool there and blur light", "The optic nerve exit lacks sensors", "The nose blocks that patch of view"], a: 2, explain: "Octopus eyes are wired differently, with nerves behind the retina, so they don't have this blind spot.", tip: "Try this: Close your left eye, stare at a dot, and slide a second dot to the right until it vanishes." },
  { id: "bo18", topic: "body", legendary: true, headline: "Your liver can regrow to full size after most of it is removed", body: "The liver can regenerate after up to about two-thirds of it is surgically removed, growing back to near its original size within weeks to months. This makes living-donor liver transplants possible.", q: "What can a healthy human liver do after a large part is removed?", options: ["Nothing; the loss is permanent", "Shrink to save energy", "Turn into scar tissue", "Regrow to near full size"], a: 3, explain: "It regains its size and function, though the regrown liver's shape can differ from the original.", tip: "Try this: Keep alcohol within your national guideline limits; heavy drinking is a leading cause of liver damage." }
);
